namespace BARANG.Core.Application.Customers;

public sealed partial class CustomerAdministration(ICustomerStore store,ITransactionExecutor transactions,ICompanyContext company,IAuditWriter audit,TimeProvider time):ICustomerAdministration,ICustomerDefaultAddressResolver
{
    private Guid Company=>company.RequireCompanyId(); private DateTimeOffset Now=>time.GetUtcNow();

    public Task<Result<CustomerView>>CreateAsync(CustomerDataCommand c,CancellationToken ct)=>transactions.ExecuteAsync(async t=>
    {
        Guid companyId=Company; var resolved=await ResolveRoot(c,null,null,t);if(resolved.IsFailure)return Result.Failure<CustomerView>(resolved.Error);c=resolved.Value; Result shape=ValidateProfileShape(c.CustomerType,c.FirstName,c.LastName,c.FatherName,c.BirthDate,c.GenderCode,c.BirthCertificateNumber,c.PlaceOfIssue,c.Occupation,c.LegalName,c.TradeName,c.RegistrationNumber,c.EstablishmentDate,c.LegalEntityTypeCode,c.BusinessActivity,c.Website,c.ManagingDirector);if(shape.IsFailure)return Result.Failure<CustomerView>(shape.Error);Result valid=await ValidateReferences(c.CustomerGroupCode,c.PriceGroupCode,c.SalesRepresentativePersonId,t);if(valid.IsFailure)return Result.Failure<CustomerView>(valid.Error);
        string display=DisplayName(c.CustomerType,c.DisplayName,c.FirstName,c.LastName,c.LegalName);
        Result<Customer> made=Customer.Create(Guid.NewGuid(),companyId,c.CustomerCode,c.CustomerType,display,c.PrimaryMobile,c.PrimaryPhone,c.PrimaryEmail,c.EconomicCode,c.CustomerGroupCode,c.PriceGroupCode,c.SalesRepresentativePersonId,c.Notes,Now);if(made.IsFailure)return Result.Failure<CustomerView>(made.Error);
        if(await store.CodeExistsAsync(made.Value.CustomerCode,t)||await store.IdentifierExistsAsync(c.CustomerType,CustomerText.Identifier(c.NationalId),CustomerText.Identifier(c.RegistrationNumber),null,t))return Result.Failure<CustomerView>(await store.CodeExistsAsync(made.Value.CustomerCode,t)?CustomerErrors.DuplicateCode:CustomerErrors.DuplicateIdentifier);
        IndividualCustomerProfile? individual=null;LegalCustomerProfile? legal=null;
        if(c.CustomerType==CustomerType.Individual){Result<IndividualCustomerProfile> profile=IndividualCustomerProfile.Create(Guid.NewGuid(),made.Value.Id,companyId,c.FirstName??"",c.LastName??"",c.NationalId,c.FatherName,c.BirthDate,c.GenderCode,c.BirthCertificateNumber,c.PlaceOfIssue,c.Occupation,Now);if(profile.IsFailure)return Result.Failure<CustomerView>(profile.Error);individual=profile.Value;store.Add(individual);}
        else {Result<LegalCustomerProfile> profile=LegalCustomerProfile.Create(Guid.NewGuid(),made.Value.Id,companyId,c.LegalName??"",c.TradeName,c.NationalId,c.RegistrationNumber,c.EstablishmentDate,c.LegalEntityTypeCode,c.BusinessActivity,c.Website,c.ManagingDirector,Now);if(profile.IsFailure)return Result.Failure<CustomerView>(profile.Error);legal=profile.Value;legal.AssignReference(c.LegalEntityTypeId);store.Add(legal);}
        made.Value.AssignReferences(c.CustomerGroupId,c.PriceGroupId);store.Add(made.Value);Write("customer.created","customer",made.Value.Id,AuditChangeKind.Added,new Dictionary<string,object?>{{"customerCode",made.Value.CustomerCode},{"customerType",made.Value.CustomerType.ToString()}});return Result.Success(await View(made.Value,individual,legal,t));
    },ct);

    public Task<Result<CustomerView>>GetAsync(Guid id,CancellationToken ct)=>Read(async t=>{Customer? x=await store.FindAsync(id,t);return x is null?Result.Failure<CustomerView>(CustomerErrors.NotFound):Result.Success(await View(x,null,null,t));},ct);
    public Task<Result<CustomerDetailsView>>GetDetailsAsync(Guid id,bool includeFinancial,CancellationToken ct)=>Read(async t=>{Customer? x=await store.FindAsync(id,t);if(x is null)return Result.Failure<CustomerDetailsView>(CustomerErrors.NotFound);CustomerView customer=await View(x,null,null,t);IReadOnlyList<CustomerAddressView> addresses=(await store.ListAddressesAsync(id,false,t)).Select(AddressView).ToArray();IReadOnlyList<CustomerContactView> contacts=x.CustomerType==CustomerType.LegalEntity?(await store.ListContactsAsync(id,false,t)).Select(ContactView).ToArray():[];CustomerFinancialView? financial=includeFinancial?FinancialView(await store.FindFinancialAsync(id,false,t),x):null;IReadOnlyList<CustomerBankAccountView> banks=includeFinancial?(await store.ListBankAccountsAsync(id,false,t)).Select(BankView).ToArray():[];return Result.Success(new CustomerDetailsView(customer,addresses,contacts,financial,banks));},ct);
    public Task<Result<CustomerView>>GetByCodeAsync(string code,CancellationToken ct)=>Read(async t=>{string? normalized=CustomerText.Code(code);if(normalized is null)return Result.Failure<CustomerView>(CustomerErrors.InvalidCode);Customer? x=await store.FindByCodeAsync(normalized,t);return x is null?Result.Failure<CustomerView>(CustomerErrors.NotFound):Result.Success(await View(x,null,null,t));},ct);
    public Task<Result<PagedResult<CustomerDirectoryView>>>SearchAsync(CustomerQuery query,CancellationToken ct)=>Read(async t=>{try{PagedResult<CustomerDirectoryRow> page=await store.SearchAsync(query,t);return Result.Success(new PagedResult<CustomerDirectoryView>(page.Items.Select(x=>DirectoryView(x.Customer,x.SalesRepresentativeName)),page.PageNumber,page.PageSize,page.TotalCount));}catch(ArgumentOutOfRangeException){return Result.Failure<PagedResult<CustomerDirectoryView>>(Error.Validation("customer.invalid_pagination"));}},ct);
    public Task<Result<IReadOnlyList<CustomerOptionView>>>OptionsAsync(string? search,bool activeOnly,int limit,CancellationToken ct)=>Read(async t=>limit is <1 or >100?Result.Failure<IReadOnlyList<CustomerOptionView>>(Error.Validation("customer.invalid_pagination")):Result.Success<IReadOnlyList<CustomerOptionView>>((await store.OptionsAsync(search,activeOnly,limit,t)).Select(x=>new CustomerOptionView(x.Id,x.CustomerCode,x.DisplayName,x.CustomerType,x.PrimaryMobile)).ToArray()),ct);
    public Task<Result<IReadOnlyList<SalesRepresentativeOption>>>SalesRepresentativesAsync(string? search,int limit,CancellationToken ct)=>Read(async t=>limit is <1 or >100?Result.Failure<IReadOnlyList<SalesRepresentativeOption>>(Error.Validation("customer.invalid_pagination")):Result.Success(await store.SalesRepresentativesAsync(search,limit,t)),ct);

    public Task<Result<CustomerView>>UpdateAsync(Guid id,CustomerUpdateCommand c,CancellationToken ct)=>transactions.ExecuteAsync(async t=>
    {
        Company.ToString();Customer? x=await store.FindAsync(id,t);if(x is null)return Result.Failure<CustomerView>(CustomerErrors.NotFound);var oldLegal=x.CustomerType==CustomerType.LegalEntity?await store.FindLegalProfileAsync(id,true,t):null;var resolved=await ResolveRoot(c,x,oldLegal,t);if(resolved.IsFailure)return Result.Failure<CustomerView>(resolved.Error);c=resolved.Value;Result shape=ValidateProfileShape(x.CustomerType,c.FirstName,c.LastName,c.FatherName,c.BirthDate,c.GenderCode,c.BirthCertificateNumber,c.PlaceOfIssue,c.Occupation,c.LegalName,c.TradeName,c.RegistrationNumber,c.EstablishmentDate,c.LegalEntityTypeCode,c.BusinessActivity,c.Website,c.ManagingDirector);if(shape.IsFailure)return Result.Failure<CustomerView>(shape.Error);Result refs=await ValidateReferences(c.CustomerGroupCode,c.PriceGroupCode,c.SalesRepresentativePersonId,t,x.SalesRepresentativePersonId);if(refs.IsFailure)return Result.Failure<CustomerView>(refs.Error);
        if(await store.IdentifierExistsAsync(x.CustomerType,CustomerText.Identifier(c.NationalId),CustomerText.Identifier(c.RegistrationNumber),id,t))return Result.Failure<CustomerView>(CustomerErrors.DuplicateIdentifier);
        string display=DisplayName(x.CustomerType,c.DisplayName,c.FirstName,c.LastName,c.LegalName);Result changed=x.Update(display,c.PrimaryMobile,c.PrimaryPhone,c.PrimaryEmail,c.EconomicCode,c.CustomerGroupCode,c.PriceGroupCode,c.SalesRepresentativePersonId,c.Notes,c.Version,Now);if(changed.IsFailure)return Result.Failure<CustomerView>(changed.Error);
        IndividualCustomerProfile? individual=null;LegalCustomerProfile? legal=null;
        if(x.CustomerType==CustomerType.Individual){individual=await store.FindIndividualProfileAsync(id,true,t);if(individual is null)return Result.Failure<CustomerView>(CustomerErrors.InvalidProfile);Result r=individual.Update(c.FirstName??"",c.LastName??"",c.NationalId,c.FatherName,c.BirthDate,c.GenderCode,c.BirthCertificateNumber,c.PlaceOfIssue,c.Occupation,c.ProfileVersion,Now);if(r.IsFailure)return Result.Failure<CustomerView>(r.Error);}
        else {legal=await store.FindLegalProfileAsync(id,true,t);if(legal is null)return Result.Failure<CustomerView>(CustomerErrors.InvalidProfile);Result r=legal.Update(c.LegalName??"",c.TradeName,c.NationalId,c.RegistrationNumber,c.EstablishmentDate,c.LegalEntityTypeCode,c.BusinessActivity,c.Website,c.ManagingDirector,c.ProfileVersion,Now);if(r.IsFailure)return Result.Failure<CustomerView>(r.Error);}
        if(c.Status is { } status&&status!=x.Status){CustomerStatus old=x.Status;Result statusChange=x.SetStatus(status,x.Version,Now);if(statusChange.IsFailure)return Result.Failure<CustomerView>(statusChange.Error);Write("customer.status.changed","customer",id,AuditChangeKind.Modified,new Dictionary<string,object?>{{"from",old.ToString()},{"to",status.ToString()}});}
        x.AssignReferences(c.CustomerGroupId,c.PriceGroupId);legal?.AssignReference(c.LegalEntityTypeId);Write("customer.updated","customer",id,AuditChangeKind.Modified,new Dictionary<string,object?>{{"customerType",x.CustomerType.ToString()}});return Result.Success(await View(x,individual,legal,t));
    },ct);
    public Task<Result<CustomerView>>SetStatusAsync(Guid id,CustomerStatus status,long version,CancellationToken ct)=>transactions.ExecuteAsync(async t=>{Company.ToString();Customer? x=await store.FindAsync(id,t);if(x is null)return Result.Failure<CustomerView>(CustomerErrors.NotFound);CustomerStatus old=x.Status;Result r=x.SetStatus(status,version,Now);if(r.IsFailure)return Result.Failure<CustomerView>(r.Error);Write("customer.status.changed","customer",id,AuditChangeKind.Modified,new Dictionary<string,object?>{{"from",old.ToString()},{"to",status.ToString()}});return Result.Success(await View(x,null,null,t));},ct);
    public Task<Result>DeleteAsync(Guid id,long version,CancellationToken ct)=>transactions.ExecuteAsync(async t=>
    {
        Company.ToString();Customer? customer=await store.FindAsync(id,t);
        if(customer is null)return Result.Failure(CustomerErrors.NotFound);
        if(customer.Version!=version)return Result.Failure(CustomerErrors.Concurrency);
        if(await store.HasProtectedDependenciesAsync(id,t))return Result.Failure(CustomerErrors.Referenced);
        await store.RemoveAggregateAsync(customer,t);
        Write("customer.deleted","customer",id,AuditChangeKind.Archived,new Dictionary<string,object?>{{"customerCode",customer.CustomerCode}});
        return Result.Success();
    },ct);

    public Task<Result<CustomerContactView>>AddContactAsync(Guid customerId,ContactCommand c,CancellationToken ct)=>transactions.ExecuteAsync(async t=>{Customer? owner=await Owner(customerId,t);if(owner is null)return Result.Failure<CustomerContactView>(CustomerErrors.NotFound);if(owner.CustomerType!=CustomerType.LegalEntity)return Result.Failure<CustomerContactView>(CustomerErrors.LegalContactRequired);var reference=await ResolveReference("contact.role",c.ContactRoleId,c.ContactTypeCode,null,null,t);if(reference.IsFailure)return Result.Failure<CustomerContactView>(reference.Error);c=c with{ContactRoleId=reference.Value?.Id,ContactTypeCode=reference.Value?.Code??""};if(c.IsPrimary)await UnsetPrimaryContacts(customerId,null,t);Result<CustomerContact> made=CustomerContact.Create(Guid.NewGuid(),customerId,owner.CompanyId,c.ContactTypeCode,c.FirstName,c.LastName,c.Mobile,c.Phone,c.Email,c.PositionTitle,c.Notes,c.IsPrimary,c.DisplayOrder,Now);if(made.IsFailure)return Result.Failure<CustomerContactView>(made.Error);made.Value.AssignReference(c.ContactRoleId);store.Add(made.Value);Write("customer.contact.created","customer_contact",made.Value.Id,AuditChangeKind.Added,new Dictionary<string,object?>{{"customerId",customerId},{"isPrimary",made.Value.IsPrimary}});return Result.Success(ContactView(made.Value));},ct);
    public Task<Result<IReadOnlyList<CustomerContactView>>>ListContactsAsync(Guid customerId,bool activeOnly,CancellationToken ct)=>Read(async t=>{Customer? owner=await store.FindAsync(customerId,t);if(owner is null)return Result.Failure<IReadOnlyList<CustomerContactView>>(CustomerErrors.NotFound);if(owner.CustomerType!=CustomerType.LegalEntity)return Result.Failure<IReadOnlyList<CustomerContactView>>(CustomerErrors.LegalContactRequired);return Result.Success<IReadOnlyList<CustomerContactView>>((await store.ListContactsAsync(customerId,activeOnly,t)).Select(ContactView).ToArray());},ct);
    public Task<Result<CustomerContactView>>UpdateContactAsync(Guid customerId,Guid id,ContactCommand c,CancellationToken ct)=>ChangeContact(customerId,id,async(x,t)=>{var reference=await ResolveReference("contact.role",c.ContactRoleId,c.ContactTypeCode,x.ContactRoleId,x.ContactTypeCode,t);if(reference.IsFailure)return Result.Failure(reference.Error);c=c with{ContactRoleId=reference.Value?.Id,ContactTypeCode=reference.Value?.Code??""};if(c.IsPrimary&&!x.IsPrimary)await UnsetPrimaryContacts(customerId,id,t);Result updated=x.Update(c.ContactTypeCode,c.FirstName,c.LastName,c.Mobile,c.Phone,c.Email,c.PositionTitle,c.Notes,c.IsPrimary,c.DisplayOrder,c.Version,Now);if(updated.IsSuccess)x.AssignReference(c.ContactRoleId);return updated;},"customer.contact.updated",ct);
    public Task<Result<CustomerContactView>>SetContactActiveAsync(Guid customerId,Guid id,bool active,long version,CancellationToken ct)=>ChangeContact(customerId,id,(x,_)=>Task.FromResult(x.SetActive(active,version,Now)),active?"customer.contact.activated":"customer.contact.deactivated",ct);
    public Task<Result<CustomerContactView>>SetPrimaryContactAsync(Guid customerId,Guid id,long version,CancellationToken ct)=>ChangeContact(customerId,id,async(x,t)=>{await UnsetPrimaryContacts(customerId,id,t);return x.SetPrimary(true,version,Now);},"customer.contact.primary.changed",ct);

    public Task<Result<CustomerAddressView>>AddAddressAsync(Guid customerId,AddressCommand c,CancellationToken ct)=>transactions.ExecuteAsync(async t=>{Customer? owner=await Owner(customerId,t);if(owner is null)return Result.Failure<CustomerAddressView>(CustomerErrors.NotFound);var resolved=await ResolveAddress(c,null,t);if(resolved.IsFailure)return Result.Failure<CustomerAddressView>(resolved.Error);c=resolved.Value;Result geo=await ValidateGeography(c.ProvinceCode,c.CityCode,t);if(geo.IsFailure)return Result.Failure<CustomerAddressView>(geo.Error);if(c.IsDefault)await UnsetDefaultAddresses(customerId,null,t);Result<CustomerAddress> made=CustomerAddress.Create(Guid.NewGuid(),customerId,owner.CompanyId,c.AddressTypeCode,c.Title,c.CountryCode,c.ProvinceCode,c.CityCode,c.District,c.AddressLine1,c.AddressLine2,c.PostalCode,c.RecipientName,c.RecipientPhone,c.RecipientMobile,c.IsDefault,c.DisplayOrder,Now);if(made.IsFailure)return Result.Failure<CustomerAddressView>(made.Error);Result details=made.Value.AssignDetails(c.AddressTypeId,c.Email,c.Notes);if(details.IsFailure)return Result.Failure<CustomerAddressView>(details.Error);store.Add(made.Value);Write("customer.address.created","customer_address",made.Value.Id,AuditChangeKind.Added,new Dictionary<string,object?>{{"customerId",customerId},{"isDefault",made.Value.IsDefault}});return Result.Success(AddressView(made.Value));},ct);
    public Task<Result<IReadOnlyList<CustomerAddressView>>>ListAddressesAsync(Guid customerId,bool activeOnly,CancellationToken ct)=>Read(async t=>await store.FindAsync(customerId,t) is null?Result.Failure<IReadOnlyList<CustomerAddressView>>(CustomerErrors.NotFound):Result.Success<IReadOnlyList<CustomerAddressView>>((await store.ListAddressesAsync(customerId,activeOnly,t)).Select(AddressView).ToArray()),ct);
    public Task<Result<CustomerAddressView>>UpdateAddressAsync(Guid customerId,Guid id,AddressCommand c,CancellationToken ct)=>ChangeAddress(customerId,id,async(x,t)=>{var resolved=await ResolveAddress(c,x,t);if(resolved.IsFailure)return Result.Failure(resolved.Error);c=resolved.Value;Result geo=await ValidateGeography(c.ProvinceCode,c.CityCode,t);if(geo.IsFailure)return geo;if(c.IsDefault&&!x.IsDefault)await UnsetDefaultAddresses(customerId,id,t);Result updated=x.Update(c.AddressTypeCode,c.Title,c.CountryCode,c.ProvinceCode,c.CityCode,c.District,c.AddressLine1,c.AddressLine2,c.PostalCode,c.RecipientName,c.RecipientPhone,c.RecipientMobile,c.IsDefault,c.DisplayOrder,c.Version,Now);return updated.IsFailure?updated:x.AssignDetails(c.AddressTypeId,c.Email,c.Notes);},"customer.address.updated",ct);
    public Task<Result<CustomerAddressView>>SetAddressActiveAsync(Guid customerId,Guid id,bool active,long version,CancellationToken ct)=>ChangeAddress(customerId,id,(x,_)=>Task.FromResult(x.SetActive(active,version,Now)),active?"customer.address.activated":"customer.address.deactivated",ct);
    public Task<Result<CustomerAddressView>>SetDefaultAddressAsync(Guid customerId,Guid id,long version,CancellationToken ct)=>ChangeAddress(customerId,id,async(x,t)=>{await UnsetDefaultAddresses(customerId,id,t);return x.SetDefault(true,version,Now);},"customer.address.default.changed",ct);

    public Task<Result<CustomerFinancialView>>GetFinancialAsync(Guid customerId,CancellationToken ct)=>Read(async t=>{Customer? owner=await store.FindAsync(customerId,t);if(owner is null)return Result.Failure<CustomerFinancialView>(CustomerErrors.NotFound);CustomerFinancialProfile? x=await store.FindFinancialAsync(customerId,false,t);return x is null?Result.Failure<CustomerFinancialView>(CustomerErrors.NotFound):Result.Success(FinancialView(x,owner)!);},ct);
    public Task<Result<CustomerFinancialView>>UpsertFinancialAsync(Guid customerId,FinancialProfileCommand c,CancellationToken ct)=>transactions.ExecuteAsync(async t=>{Customer? owner=await Owner(customerId,t);if(owner is null)return Result.Failure<CustomerFinancialView>(CustomerErrors.NotFound);CustomerFinancialProfile? x=await store.FindFinancialAsync(customerId,true,t);var resolved=await ResolveFinancial(c,x,t);if(resolved.IsFailure)return Result.Failure<CustomerFinancialView>(resolved.Error);c=resolved.Value;if(x is null){Result<CustomerFinancialProfile> made=CustomerFinancialProfile.Create(Guid.NewGuid(),customerId,owner.CompanyId,c.CreditLimit,c.PaymentTermCode,c.PaymentConditionCode,c.PreferredPaymentMethodCode,c.DefaultDiscountPercent,c.FinancialStatus,c.TaxStatusCode,c.DefaultCurrencyCode,Now);if(made.IsFailure)return Result.Failure<CustomerFinancialView>(made.Error);x=made.Value;store.Add(x);}else{Result r=x.Update(c.CreditLimit,c.PaymentTermCode,c.PaymentConditionCode,c.PreferredPaymentMethodCode,c.DefaultDiscountPercent,c.FinancialStatus,c.TaxStatusCode,c.DefaultCurrencyCode,c.Version,Now);if(r.IsFailure)return Result.Failure<CustomerFinancialView>(r.Error);}x.AssignReferences(c.PaymentTermId,c.PaymentConditionId,c.PreferredPaymentMethodId,c.TaxStatusId);Write("customer.financial.updated","customer_financial_profile",x.Id,AuditChangeKind.Modified,new Dictionary<string,object?>{{"customerId",customerId},{"creditLimit",x.CreditLimit},{"discount",x.DefaultDiscountPercent}});return Result.Success(FinancialView(x,owner)!);},ct);

    public Task<Result<IReadOnlyList<CustomerBankAccountView>>>ListBankAccountsAsync(Guid customerId,bool activeOnly,CancellationToken ct)=>Read(async t=>await store.FindAsync(customerId,t) is null?Result.Failure<IReadOnlyList<CustomerBankAccountView>>(CustomerErrors.NotFound):Result.Success<IReadOnlyList<CustomerBankAccountView>>((await store.ListBankAccountsAsync(customerId,activeOnly,t)).Select(BankView).ToArray()),ct);
    public Task<Result<CustomerBankAccountView>>AddBankAccountAsync(Guid customerId,BankAccountCommand c,CancellationToken ct)=>transactions.ExecuteAsync(async t=>{Customer? owner=await Owner(customerId,t);if(owner is null)return Result.Failure<CustomerBankAccountView>(CustomerErrors.NotFound);var resolved=await ResolveBank(c,null,t);if(resolved.IsFailure)return Result.Failure<CustomerBankAccountView>(resolved.Error);c=resolved.Value;string? account=CustomerText.Identifier(c.AccountNumber),iban=NormalizeIban(c.Iban);if(await store.BankAccountExistsAsync(customerId,account,iban,null,t))return Result.Failure<CustomerBankAccountView>(CustomerErrors.DuplicateBankAccount);if(c.IsDefault)await UnsetDefaultBanks(customerId,null,t);Result<CustomerBankAccount> made=CustomerBankAccount.Create(Guid.NewGuid(),customerId,owner.CompanyId,c.BankCode,c.BankName,c.AccountNumber,c.Iban,c.AccountHolderName,c.CurrencyCode,c.IsDefault,c.Notes,Now);if(made.IsFailure)return Result.Failure<CustomerBankAccountView>(made.Error);Result details=made.Value.AssignDetails(c.BankId,c.AccountTypeId,c.AccountTypeCode,c.AccountName,c.OwnershipType,c.CardNumber,c.BranchCode);if(details.IsFailure)return Result.Failure<CustomerBankAccountView>(details.Error);store.Add(made.Value);Write("customer.bank.created","customer_bank_account",made.Value.Id,AuditChangeKind.Added,new Dictionary<string,object?>{{"customerId",customerId},{"isDefault",made.Value.IsDefault}});return Result.Success(BankView(made.Value));},ct);
    public Task<Result<CustomerBankAccountView>>UpdateBankAccountAsync(Guid customerId,Guid id,BankAccountCommand c,CancellationToken ct)=>ChangeBank(customerId,id,async(x,t)=>{var resolved=await ResolveBank(c,x,t);if(resolved.IsFailure)return Result.Failure(resolved.Error);c=resolved.Value;string? account=CustomerText.Identifier(c.AccountNumber),iban=NormalizeIban(c.Iban);if(await store.BankAccountExistsAsync(customerId,account,iban,id,t))return Result.Failure(CustomerErrors.DuplicateBankAccount);if(c.IsDefault&&!x.IsDefault)await UnsetDefaultBanks(customerId,id,t);Result updated=x.Update(c.BankCode,c.BankName,c.AccountNumber,c.Iban,c.AccountHolderName,c.CurrencyCode,c.IsDefault,c.Notes,c.Version,Now);return updated.IsFailure?updated:x.AssignDetails(c.BankId,c.AccountTypeId,c.AccountTypeCode,c.AccountName,c.OwnershipType,c.CardNumber,c.BranchCode);},"customer.bank.updated",ct);
    public Task<Result<CustomerBankAccountView>>SetBankAccountActiveAsync(Guid customerId,Guid id,bool active,long version,CancellationToken ct)=>ChangeBank(customerId,id,(x,_)=>Task.FromResult(x.SetActive(active,version,Now)),active?"customer.bank.activated":"customer.bank.deactivated",ct);
    public Task<Result<CustomerBankAccountView>>SetDefaultBankAccountAsync(Guid customerId,Guid id,long version,CancellationToken ct)=>ChangeBank(customerId,id,async(x,t)=>{await UnsetDefaultBanks(customerId,id,t);return x.SetDefault(true,version,Now);},"customer.bank.default.changed",ct);

    private async Task<Result>ValidateReferences(string? group,string? price,Guid? sales,CancellationToken t,Guid? previousSales=null){if(sales is Guid person&&sales!=previousSales&&!await store.SalesRepresentativeExistsAsync(person,t))return Result.Failure(CustomerErrors.InvalidReference);return Result.Success();}
    private static Result ValidateProfileShape(CustomerType type,string? first,string? last,string? father,DateOnly? birth,string? gender,string? certificate,string? place,string? occupation,string? legal,string? trade,string? registration,DateOnly? establishment,string? legalType,string? activity,string? website,string? director)
    {
        bool individualData=new[]{first,last,father,gender,certificate,place,occupation}.Any(static x=>!string.IsNullOrWhiteSpace(x))||birth is not null;
        bool legalData=new[]{legal,trade,registration,legalType,activity,website,director}.Any(static x=>!string.IsNullOrWhiteSpace(x))||establishment is not null;
        return type switch{CustomerType.Individual when legalData=>Result.Failure(CustomerErrors.InvalidProfile),CustomerType.LegalEntity when individualData=>Result.Failure(CustomerErrors.InvalidProfile),CustomerType.Individual or CustomerType.LegalEntity=>Result.Success(),_=>Result.Failure(CustomerErrors.InvalidProfile)};
    }
    private async Task<Result>ValidateGeography(string? province,string? city,CancellationToken t){if(string.IsNullOrWhiteSpace(city))return Result.Success();if(string.IsNullOrWhiteSpace(province)||!await store.CityBelongsToProvinceAsync(province.Trim().ToLowerInvariant(),city.Trim().ToLowerInvariant(),t))return Result.Failure(CustomerErrors.InvalidReference);return Result.Success();}
    private async Task UnsetPrimaryContacts(Guid id,Guid? exclude,CancellationToken t){foreach(CustomerContact x in await store.ListPrimaryContactsAsync(id,exclude,t))x.SetPrimary(false,x.Version,Now);await store.FlushAsync(t);}
    private async Task UnsetDefaultAddresses(Guid id,Guid? exclude,CancellationToken t){foreach(CustomerAddress x in await store.ListDefaultAddressesAsync(id,exclude,t))x.SetDefault(false,x.Version,Now);await store.FlushAsync(t);}
    private async Task UnsetDefaultBanks(Guid id,Guid? exclude,CancellationToken t){foreach(CustomerBankAccount x in await store.ListDefaultBankAccountsAsync(id,exclude,t))x.SetDefault(false,x.Version,Now);}
    private Task<Result<CustomerContactView>>ChangeContact(Guid customerId,Guid id,Func<CustomerContact,CancellationToken,Task<Result>> op,string action,CancellationToken ct)=>transactions.ExecuteAsync(async t=>{Customer? owner=await Owner(customerId,t);if(owner is null)return Result.Failure<CustomerContactView>(CustomerErrors.NotFound);if(owner.CustomerType!=CustomerType.LegalEntity)return Result.Failure<CustomerContactView>(CustomerErrors.LegalContactRequired);CustomerContact? x=await store.FindContactAsync(customerId,id,t);if(x is null)return Result.Failure<CustomerContactView>(CustomerErrors.ContactNotFound);Result r=await op(x,t);if(r.IsFailure)return Result.Failure<CustomerContactView>(r.Error);Write(action,"customer_contact",id,AuditChangeKind.Modified,new Dictionary<string,object?>{{"customerId",customerId}});return Result.Success(ContactView(x));},ct);
    private Task<Result<CustomerAddressView>>ChangeAddress(Guid customerId,Guid id,Func<CustomerAddress,CancellationToken,Task<Result>> op,string action,CancellationToken ct)=>transactions.ExecuteAsync(async t=>{if(await Owner(customerId,t) is null)return Result.Failure<CustomerAddressView>(CustomerErrors.NotFound);CustomerAddress? x=await store.FindAddressAsync(customerId,id,t);if(x is null)return Result.Failure<CustomerAddressView>(CustomerErrors.AddressNotFound);Result r=await op(x,t);if(r.IsFailure)return Result.Failure<CustomerAddressView>(r.Error);Write(action,"customer_address",id,AuditChangeKind.Modified,new Dictionary<string,object?>{{"customerId",customerId}});return Result.Success(AddressView(x));},ct);
    private Task<Result<CustomerBankAccountView>>ChangeBank(Guid customerId,Guid id,Func<CustomerBankAccount,CancellationToken,Task<Result>> op,string action,CancellationToken ct)=>transactions.ExecuteAsync(async t=>{if(await Owner(customerId,t) is null)return Result.Failure<CustomerBankAccountView>(CustomerErrors.NotFound);CustomerBankAccount? x=await store.FindBankAccountAsync(customerId,id,t);if(x is null)return Result.Failure<CustomerBankAccountView>(CustomerErrors.BankAccountNotFound);Result r=await op(x,t);if(r.IsFailure)return Result.Failure<CustomerBankAccountView>(r.Error);Write(action,"customer_bank_account",id,AuditChangeKind.Modified,new Dictionary<string,object?>{{"customerId",customerId}});return Result.Success(BankView(x));},ct);
    private Task<Result<T>>Read<T>(Func<CancellationToken,Task<Result<T>>> operation,CancellationToken ct){Company.ToString();return transactions.ExecuteAsync(operation,ct);}private async Task<Customer?>Owner(Guid id,CancellationToken t){Company.ToString();return await store.LockOwnerAsync(id,t);}
    private static string DisplayName(CustomerType type,string? display,string? first,string? last,string? legal){if(!string.IsNullOrWhiteSpace(display))return display.Trim();return type==CustomerType.Individual?string.Join(' ',new[]{first?.Trim(),last?.Trim()}.Where(x=>!string.IsNullOrWhiteSpace(x))):legal?.Trim()??"";}
    private async Task<CustomerView>View(Customer x,IndividualCustomerProfile? individual,LegalCustomerProfile? legal,CancellationToken t){individual??=x.CustomerType==CustomerType.Individual?await store.FindIndividualProfileAsync(x.Id,false,t):null;legal??=x.CustomerType==CustomerType.LegalEntity?await store.FindLegalProfileAsync(x.Id,false,t):null;return new CustomerView(x.Id,x.CompanyId,x.CustomerCode,x.CustomerType,x.DisplayName,x.Status,x.PrimaryMobile,x.PrimaryPhone,x.PrimaryEmail,x.EconomicCode,x.CustomerGroupCode,x.PriceGroupCode,x.SalesRepresentativePersonId,await store.SalesRepresentativeNameAsync(x.SalesRepresentativePersonId,t),x.Notes,x.CreatedAtUtc,x.UpdatedAtUtc,x.Version,individual is null?null:new(individual.Id,individual.FirstName,individual.LastName,individual.NationalId,individual.FatherName,individual.BirthDate,individual.GenderCode,individual.BirthCertificateNumber,individual.PlaceOfIssue,individual.Occupation,individual.Version),legal is null?null:new(legal.Id,legal.LegalName,legal.TradeName,legal.NationalId,legal.RegistrationNumber,legal.EstablishmentDate,legal.LegalEntityTypeCode,legal.BusinessActivity,legal.Website,legal.ManagingDirector,legal.Version){LegalEntityTypeId=legal.LegalEntityTypeId}){CustomerGroupId=x.CustomerGroupId,PriceGroupId=x.PriceGroupId};}
    private static CustomerDirectoryView DirectoryView(Customer x,string? sales)=>new(x.Id,x.CustomerCode,x.DisplayName,x.CustomerType,x.PrimaryMobile,x.CustomerGroupCode,sales,x.Status,x.Version);
    private static CustomerContactView ContactView(CustomerContact x)=>new(x.Id,x.CustomerId,x.ContactTypeCode,x.FirstName,x.LastName,x.Mobile,x.Phone,x.Email,x.PositionTitle,x.Notes,x.IsPrimary,x.IsActive,x.DisplayOrder,x.Version){ContactRoleId=x.ContactRoleId};
    private static CustomerAddressView AddressView(CustomerAddress x)=>new(x.Id,x.CustomerId,x.AddressTypeCode,x.Title,x.CountryCode,x.ProvinceCode,x.CityCode,x.District,x.AddressLine1,x.AddressLine2,x.PostalCode,x.RecipientName,x.RecipientPhone,x.RecipientMobile,x.IsDefault,x.IsActive,x.DisplayOrder,x.Version){AddressTypeId=x.AddressTypeId,Email=x.Email,Notes=x.Notes};
    private static CustomerFinancialView?FinancialView(CustomerFinancialProfile? x,Customer owner){if(x is null)return null;const decimal used=0m,balance=0m;return new(x.Id,x.CustomerId,x.CreditLimit,used,Math.Max(0,x.CreditLimit-used),x.PaymentTermCode,x.PaymentConditionCode,x.PreferredPaymentMethodCode,x.DefaultDiscountPercent,owner.PriceGroupCode,owner.CustomerGroupCode,owner.SalesRepresentativePersonId,x.FinancialStatus,balance,"NotConnected",x.TaxStatusCode,x.DefaultCurrencyCode,x.Version){PaymentTermId=x.PaymentTermId,PaymentConditionId=x.PaymentConditionId,PreferredPaymentMethodId=x.PreferredPaymentMethodId,TaxStatusId=x.TaxStatusId};}
    private static CustomerBankAccountView BankView(CustomerBankAccount x)=>new(x.Id,x.CustomerId,x.BankCode,x.BankName,x.AccountNumber,x.Iban,x.AccountHolderName,x.CurrencyCode,x.IsDefault,x.IsActive,x.Notes,x.Version){BankId=x.BankId,AccountTypeId=x.AccountTypeId,AccountTypeCode=x.AccountTypeCode,AccountName=x.AccountName,OwnershipType=x.OwnershipType,CardNumber=x.CardNumber,BranchCode=x.BranchCode};
    private static string?NormalizeIban(string? value){string v=new((value??"").Where(char.IsLetterOrDigit).Select(char.ToUpperInvariant).ToArray());return v.Length==0?null:v;}
    private void Write(string action,string entity,Guid id,AuditChangeKind kind,IReadOnlyDictionary<string,object?>? metadata=null)=>audit.Write(new(action,entity,id.ToString(),CompanyId:Company,ChangeKind:kind,Metadata:metadata));
}
